CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
-- Initial business schema for empty databases only.
CREATE TABLE "customers" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "firstName" character varying(100) NOT NULL, "lastName" character varying(100) NOT NULL, "phone" character varying(20) NOT NULL, "email" character varying(150), "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "PK_133ec679a801fab5e070f73d3ea" PRIMARY KEY ("id"));
CREATE TABLE "addresses" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "type" character varying(50) NOT NULL, "recipient" character varying(150) NOT NULL, "phone" character varying(20) NOT NULL, "department" character varying(100) NOT NULL, "province" character varying(100) NOT NULL, "district" character varying(100) NOT NULL, "address" character varying(255) NOT NULL, "reference" character varying(255), "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "customer_id" uuid, CONSTRAINT "PK_745d8f43d3af10ab8247465e450" PRIMARY KEY ("id"));
CREATE TABLE "categories" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "name" character varying(100) NOT NULL, "description" character varying(255), "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "PK_24dbc6126a28ff948da33e97d3b" PRIMARY KEY ("id"));
CREATE TABLE "products" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "name" character varying(150) NOT NULL, "slug" character varying(180) NOT NULL, "description" character varying(500), "brand" character varying(100), "status" character varying(20) NOT NULL DEFAULT 'ACTIVE', "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "category_id" uuid, CONSTRAINT "UQ_464f927ae360106b783ed0b4106" UNIQUE ("slug"), CONSTRAINT "PK_0806c755e0aca124e67c0cf6d7d" PRIMARY KEY ("id"));
CREATE TABLE "units" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "name" character varying(50) NOT NULL, "abbreviation" character varying(10) NOT NULL, "type" character varying(20) NOT NULL, "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "PK_5a8f2f064919b587d93936cb223" PRIMARY KEY ("id"));
CREATE TABLE "product_units" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "conversionFactor" numeric(12,4) NOT NULL, "price" numeric(12,2) NOT NULL, "trackStock" boolean NOT NULL DEFAULT false, "isPurchaseUnit" boolean NOT NULL DEFAULT false, "isSaleUnit" boolean NOT NULL DEFAULT false, "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "product_id" uuid, "unit_id" uuid, CONSTRAINT "PK_d26a9abe8b38cdd765716265977" PRIMARY KEY ("id"));
CREATE TABLE "inventory_movements" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "type" character varying(20) NOT NULL, "quantity" numeric(12,4) NOT NULL, "previous_quantity" numeric(12,4) NOT NULL, "new_quantity" numeric(12,4) NOT NULL, "reason" character varying(100) NOT NULL, "reference_id" uuid, "created_at" TIMESTAMP NOT NULL DEFAULT now(), "inventory_id" uuid, CONSTRAINT "PK_d7597827c1dcffae889db3ab873" PRIMARY KEY ("id"));
CREATE TABLE "inventory" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "quantity" numeric(12,4) NOT NULL DEFAULT '0', "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "product_unit_id" uuid, CONSTRAINT "REL_97bd5e57f9842904b521ecc156" UNIQUE ("product_unit_id"), CONSTRAINT "PK_82aa5da437c5bbfb80703b08309" PRIMARY KEY ("id"));
CREATE TABLE "quote_items" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "itemType" character varying(20) NOT NULL DEFAULT 'PRODUCT', "description" character varying(255) NOT NULL, "quantity" numeric(12,4) NOT NULL, "unitPrice" numeric(12,2) NOT NULL, "subtotal" numeric(12,2) NOT NULL, "created_at" TIMESTAMP NOT NULL DEFAULT now(), "quote_id" uuid, "product_unit_id" uuid, CONSTRAINT "PK_135ad3f02b5abcf65fb5cb20ad2" PRIMARY KEY ("id"));
CREATE TABLE "quotes" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "quote_date" date NOT NULL, "valid_until" date, "status" character varying(20) NOT NULL DEFAULT 'DRAFT', "subtotal" numeric(12,2) NOT NULL DEFAULT '0', "discount" numeric(12,2) NOT NULL DEFAULT '0', "total" numeric(12,2) NOT NULL DEFAULT '0', "notes" character varying(500), "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "customer_id" uuid, CONSTRAINT "PK_99a0e8bcbcd8719d3a41f23c263" PRIMARY KEY ("id"));
CREATE TABLE "order_items" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "itemType" character varying(20) NOT NULL DEFAULT 'PRODUCT', "description" character varying(255) NOT NULL, "quantity" numeric(12,4) NOT NULL, "unitPrice" numeric(12,2) NOT NULL, "subtotal" numeric(12,2) NOT NULL, "created_at" TIMESTAMP NOT NULL DEFAULT now(), "order_id" uuid, "product_unit_id" uuid, CONSTRAINT "PK_005269d8574e6fac0493715c308" PRIMARY KEY ("id"));
CREATE TABLE "orders" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "order_date" date NOT NULL, "status" character varying(20) NOT NULL DEFAULT 'PENDING', "subtotal" numeric(12,2) NOT NULL DEFAULT '0', "agreed_price" numeric(12,2), "discount" numeric(12,2) NOT NULL DEFAULT '0', "total" numeric(12,2) NOT NULL DEFAULT '0', "notes" character varying(500), "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "customer_id" uuid, "quote_id" uuid, CONSTRAINT "PK_710e2d4957aa5878dfe94e4ac2f" PRIMARY KEY ("id"));
CREATE TABLE "payments" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "payment_date" date NOT NULL, "method" character varying(20) NOT NULL, "amount" numeric(12,2) NOT NULL, "reference" character varying(100), "notes" character varying(500), "created_at" TIMESTAMP NOT NULL DEFAULT now(), "order_id" uuid, CONSTRAINT "PK_197ab7af18c93fbb0c9b28b4a59" PRIMARY KEY ("id"));
CREATE TABLE "service_providers" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "name" character varying(150) NOT NULL, "type" character varying(50) NOT NULL, "phone" character varying(30), "notes" character varying(500), "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "PK_73c86f1298c5285d76e66da2da9" PRIMARY KEY ("id"));
CREATE TABLE "production_tasks" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "description" character varying(255) NOT NULL, "quantity" numeric(12,4) NOT NULL, "unitCost" numeric(12,2) NOT NULL, "subtotal" numeric(12,2) NOT NULL, "status" character varying(20) NOT NULL DEFAULT 'PENDING', "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "production_id" uuid, "service_provider_id" uuid, CONSTRAINT "PK_2e650b46a4eb798dbb97b61973e" PRIMARY KEY ("id"));
CREATE TABLE "productions" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "status" character varying(20) NOT NULL DEFAULT 'PENDING', "started_at" TIMESTAMP, "completed_at" TIMESTAMP, "notes" character varying(500), "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "order_id" uuid, CONSTRAINT "PK_395fda0b6f26cb5fd9a2aa6315c" PRIMARY KEY ("id"));
CREATE TABLE "production_materials" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "description" character varying(255), "quantity" numeric(12,4) NOT NULL, "unitCost" numeric(12,2) NOT NULL, "subtotal" numeric(12,2) NOT NULL, "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "production_id" uuid, "product_unit_id" uuid, CONSTRAINT "PK_dbb016530a71b25364eb0e404ef" PRIMARY KEY ("id"));
CREATE TABLE "suppliers" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "name" character varying(150) NOT NULL, "phone" character varying(20), "email" character varying(150), "address" character varying(255), "notes" character varying(500), "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "PK_b70ac51766a9e3144f778cfe81e" PRIMARY KEY ("id"));
CREATE TABLE "purchases" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "purchase_date" date NOT NULL, "status" character varying(20) NOT NULL DEFAULT 'PENDING', "notes" character varying(500), "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "supplier_id" uuid, CONSTRAINT "PK_1d55032f37a34c6eceacbbca6b8" PRIMARY KEY ("id"));
CREATE TABLE "purchase_items" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "quantity" numeric(12,4) NOT NULL, "unitCost" numeric(12,2) NOT NULL, "subtotal" numeric(12,2) NOT NULL, "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), "purchase_id" uuid, "product_unit_id" uuid, CONSTRAINT "PK_e3d9bea880baad86ff6de3290da" PRIMARY KEY ("id"));
